asoslangan","start":5360,"end":5368,"surface":"based on","id":"cef7aa99-98e6-596b-bc20-436c23427d04","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"4980e436-bbb8-534b-bbba-41bc890532a9","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5360-5368:6223d8f33e09d4f70642ec5238e39537b5cc45b3816295e343e53981bf3c3750","target":true},{"term":"data","partOfSpeech":"noun","definitionEn":"facts, measurements or observations collected in research","translationUz":"tadqiqot ma’lumotlari","start":5369,"end":5373,"surface":"data","id":"22211545-4664-5d42-a585-2b9b9bf2cbfa","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"6b2a29ca-86a3-5516-b021-234db13af01e","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5369-5373:8571761457a502d9afbc9284c61dbebb862e8d48b6e43b6d5700c13a3c9865b4","target":true},{"term":"rather than","partOfSpeech":"conjunction","definitionEn":"in preference to the other thing mentioned","translationUz":"… o‘rniga","start":5374,"end":5385,"surface":"rather than","id":"d71142ff-c55b-5208-9fa2-c3e4e861a6bb","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"93aa6095-0ece-584d-b297-0b281fd0fabe","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5374-5385:58ea4bcd124504ea9d1c0664d58de3f3c874a60643f010561af945628e77c05d","target":true},{"term":"belief","partOfSpeech":"noun","definitionEn":"acceptance that something is true without reference to evidence here","translationUz":"ishonch","start":5386,"end":5392,"surface":"belief","id":"dfbc1d4f-de52-518e-a1b3-e69445bd5f09","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"6545feb8-2160-5afc-aa21-5c5441505e4a","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5386-5392:7ae8b6f6aa93ccfdce9e279305f765a45914a3693ba6e313783d1985a17894fa","target":true},{"term":"in the end","partOfSpeech":"idiom","definitionEn":"after all aspects of the question have been considered","translationUz":"oxir-oqibat","start":5414,"end":5424,"surface":"in the end","id":"4edc5aa8-072b-57f3-9dcb-58a4e5d58e5e","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"f31e20a1-e825-58cb-8a58-431cb210d500","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5414-5424:3e0c10843b546f8e03ede889ffc956868ecf5ead4226ed4170b1b40f6163cdb0","target":true},{"term":"really matter","partOfSpeech":"verb phrase","definitionEn":"have genuine importance","translationUz":"haqiqatan ahamiyatli bo‘lmoq","start":5436,"end":5449,"surface":"really matter","id":"afe00351-001d-502d-a583-75e32673bc6d","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"a0bcb9d5-42ab-50e3-9877-2b81dd6fb696","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5436-5449:eac0304d8bbc8275abd48e8dd4d4416fb0df0683a66b240b870fe56cf031c1bc","target":true},{"term":"works","partOfSpeech":"verb","definitionEn":"has its intended effect","translationUz":"samara beradi","start":5457,"end":5462,"surface":"works","id":"2608c68b-1aee-5c81-9787-dafbfd448784","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"c325db7e-2b96-565b-b802-7ae01abf4b5a","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5457-5462:916a6948bbd49b77d96f557b9082084909a60cc0d58274e6f579a4f873920d2a","target":true},{"term":"as long as","partOfSpeech":"conjunction","definitionEn":"provided that a stated condition is met","translationUz":"… sharti bilan","start":5465,"end":5475,"surface":"as long as","id":"171ced5d-00dd-5dd1-b98d-62707897c29c","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"84a13204-6267-547a-bdf9-315e689a44b5","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5465-5475:d688eaf07bc8ec0429ab990223ae06bbfea6d1765bd86dd845ae123d16dc6d18","target":true},{"term":"helps","partOfSpeech":"verb","definitionEn":"has a beneficial effect on someone","translationUz":"yordam beradi","start":5479,"end":5484,"surface":"helps","id":"81d1ca3e-a452-595d-aeb3-3c0480d5f60f","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"d2a219de-23b8-5a9f-a329-7fa701289bcb","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:5479-5484:ea7dfb781f7977f746f52312751223a798eb49649d5946949f2e42c5b7e8fae9","target":true},{"term":"given","partOfSpeech":"verb","definitionEn":"administered or delivered to the participant","translationUz":"berilgan","start":1684,"end":1689,"surface":"given","id":"93c0afb4-5e61-541f-8c40-fb04defd6764","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"e76449f0-54bb-5244-8171-e657d603367f","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:1684-1689:b189e50770a1cbdd7556f31170d9740129b9664fb4c608ccaf63154e34d86e79","target":true},{"term":"given","partOfSpeech":"verb","definitionEn":"administered or delivered to the participant","translationUz":"berilgan","start":1867,"end":1872,"surface":"given","id":"fbe0f8f0-bebc-5bb9-98d6-5fdc23813366","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"a9fd7ce6-f9e3-58aa-9d39-3a7102f7c34b","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:1867-1872:b189e50770a1cbdd7556f31170d9740129b9664fb4c608ccaf63154e34d86e79","target":true},{"term":"put in a scanner","partOfSpeech":"verb phrase","definitionEn":"placed inside a machine that records brain activity","translationUz":"miya faoliyatini qayd etuvchi skanerga joylashtirilgan","start":2745,"end":2761,"surface":"put in a scanner","id":"78a26525-8db3-5a27-9b56-ee6ed4cf6173","oldLexemeId":null,"oldSurface":null,"isNew":true,"lexemeId":"3ec9fc16-2c5d-55a2-8b11-b11137dcabf0","senseKey":"reading:94e45a16-0f2b-4de0-b6f7-80f74ccfeb43:0a7ffffc254ceac113132dfb466fe72d6eb9751077a0b5cb9d32b2e5e373c283:2745-2761:86f0b5f354e3d2c90c7415e0aec25a3dfb37f745587586dba602bc60b6a3611e","target":true}]}]}'::jsonb;
  passage jsonb;
  item jsonb;
  source text;
  current_row public.lexical_occurrences%ROWTYPE;
  before_users text;
  after_users text;
  before_lexemes text;
  after_lexemes text;
  planned_ids uuid[];
BEGIN
  IF jsonb_array_length(manifest->'passages') <> 2 OR
     (SELECT count(DISTINCT p->>'id') FROM jsonb_array_elements(manifest->'passages') p) <> 2 THEN
    RAISE EXCEPTION 'reading_pair_requires_two_passages';
  END IF;
  SELECT array_agg((e->>'lexemeId')::uuid) INTO planned_ids
    FROM jsonb_array_elements(manifest->'passages') p,
         jsonb_array_elements(p->'entries') e;
  SELECT md5(coalesce(string_agg(to_jsonb(v)::text,'' ORDER BY id),''))
    INTO before_users FROM public.user_vocabulary v;
  SELECT md5(coalesce(string_agg(to_jsonb(l)::text,'' ORDER BY id),''))
    INTO before_lexemes FROM public.lexemes l WHERE NOT (id=ANY(planned_ids));
  -- Lock both canonical bodies in stable order before changing either passage.
  PERFORM id FROM public.reading_passages WHERE id IN
    (SELECT (p->>'id')::uuid FROM jsonb_array_elements(manifest->'passages') p)
    ORDER BY id FOR SHARE;
  FOR passage IN SELECT value FROM jsonb_array_elements(manifest->'passages') LOOP
    SELECT body_text INTO STRICT source FROM public.reading_passages WHERE id=(passage->>'id')::uuid;
    IF encode(sha256(convert_to(source,'UTF8')),'hex') <> passage->>'sourceSha256' THEN
      RAISE EXCEPTION 'reading_pair_source_changed: %',passage->>'id';
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(passage->'entries') LOOP
      IF (item->>'start')::int < 0 OR (item->>'end')::int <= (item->>'start')::int OR
         substring(source FROM (item->>'start')::int+1 FOR (item->>'end')::int-(item->>'start')::int)
           IS DISTINCT FROM item->>'surface' THEN
        RAISE EXCEPTION 'reading_pair_span_changed: %',item->>'id';
      END IF;
      INSERT INTO public.lexemes(id,term,part_of_speech,definition_en,translation_uz,sense_key,
          provenance,verification_status,import_batch)
        VALUES((item->>'lexemeId')::uuid,item->>'term',item->>'partOfSpeech',item->>'definitionEn',
          item->>'translationUz',item->>'senseKey','authored','verified',manifest->>'release')
        ON CONFLICT(id) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM public.lexemes WHERE id=(item->>'lexemeId')::uuid
          AND term=item->>'term' AND part_of_speech=item->>'partOfSpeech'
          AND definition_en=item->>'definitionEn' AND translation_uz=item->>'translationUz'
          AND sense_key=item->>'senseKey') THEN
        RAISE EXCEPTION 'reading_pair_meaning_collision: %',item->>'lexemeId';
      END IF;
      SELECT * INTO current_row FROM public.lexical_occurrences WHERE id=(item->>'id')::uuid FOR UPDATE;
      IF FOUND THEN
        IF current_row.source_type <> 'reading' OR current_row.passage_id <> (passage->>'id')::uuid
           OR current_row.start_char <> (item->>'start')::int OR current_row.end_char <> (item->>'end')::int THEN
          RAISE EXCEPTION 'reading_pair_identity_changed: %',item->>'id';
        END IF;
        IF current_row.lexeme_id=(item->>'lexemeId')::uuid AND current_row.surface_form=item->>'surface'
           AND current_row.is_target_vocabulary=(item->>'target')::boolean
           AND current_row.resolution_status='resolved' AND current_row.resolution_source='authored-context' THEN
          CONTINUE;
        END IF;
        IF (item->>'isNew')::boolean OR current_row.lexeme_id IS DISTINCT FROM (item->>'oldLexemeId')::uuid
           OR current_row.surface_form IS DISTINCT FROM item->>'oldSurface' THEN
          RAISE EXCEPTION 'reading_pair_previous_binding_changed: %',item->>'id';
        END IF;
        UPDATE public.lexical_occurrences SET lexeme_id=(item->>'lexemeId')::uuid,
          lexical_unit_id=NULL,surface_form=item->>'surface',
          is_target_vocabulary=(item->>'target')::boolean,
          resolution_status='resolved',resolution_source='authored-context' WHERE id=current_row.id;
      ELSE
        IF NOT (item->>'isNew')::boolean THEN
          RAISE EXCEPTION 'reading_pair_existing_id_missing: %',item->>'id';
        END IF;
        INSERT INTO public.lexical_occurrences(id,passage_id,lexeme_id,source_type,start_char,end_char,
            surface_form,occurrence_type,is_target_vocabulary,resolution_status,resolution_source)
          VALUES((item->>'id')::uuid,(passage->>'id')::uuid,(item->>'lexemeId')::uuid,'reading',
            (item->>'start')::int,(item->>'end')::int,item->>'surface',
            CASE WHEN item->>'surface' ~ '\s' THEN 'phrase' ELSE 'word' END,
            (item->>'target')::boolean,'resolved','authored-context');
      END IF;
    END LOOP;
  END LOOP;
  SELECT md5(coalesce(string_agg(to_jsonb(v)::text,'' ORDER BY id),''))
    INTO after_users FROM public.user_vocabulary v;
  SELECT md5(coalesce(string_agg(to_jsonb(l)::text,'' ORDER BY id),''))
    INTO after_lexemes FROM public.lexemes l WHERE NOT (id=ANY(planned_ids));
  IF before_users IS DISTINCT FROM after_users OR before_lexemes IS DISTINCT FROM after_lexemes THEN
    RAISE EXCEPTION 'reading_pair_changed_preserved_state';
  END IF;
END $reading_pair$;
COMMIT;
